bool ScriptSession::startProduction(std::uint32_t handle) {
    if(!alive(handle,NativeKind::Unit))return false;auto u=units_.at(handle);if(u->removing || u->unsummon || u->construction || u->buildingUpgrade || u->hidden() || u->paused || u->abilitiesDisabled() || u->productionBlocked() || number(u->life)<=0 || u->production.empty())return false;auto& job=u->production.front();if(job.revival && (!alive(job.hero,NativeKind::Unit) || units_.at(job.hero)->removing || units_.at(job.hero)->owner!=u->owner || number(units_.at(job.hero)->life)>0 || units_.at(job.hero)->revivalTicket!=job.ticket)){cancelProduction(handle,0);return false;}if(job.started)return true;auto& states=config_.players[u->owner].states;if(job.food>0 && states[5]>std::min(states[4],states[6])-job.food)return false;job.started=true;job.reserved=!job.research;auto ticket=job.ticket;bool researching=job.research,reviving=job.revival;auto hero=job.hero;ScriptContext context;if(researching)context.researched=job.type;else context.trainedType=job.type;int food=job.food;if(!researching)adjustFood(u->owner,food,0);if(alive(handle,NativeKind::Unit) && !u->production.empty() && u->production.front().ticket==ticket){if(reviving)unitEvent(hero,44,81);else unitEvent(handle,researching?35:32,researching?72:69,context);}return true;
}
