        if(front.sacrificialWorker){auto point=spawnPoint(*u,front.type);if(!point)continue;auto job=front;u->production.pop_front();auto worker=units_.at(job.sacrificialWorker);worker->sacrificePit=0;auto owner=u->owner;auto ownerRevision=u->ownerRevision,deathRevision=u->deathRevision;auto rally=u->rally;auto target=u->rallyTarget;removeUnit(job.sacrificialWorker);if(!alive(id,NativeKind::Unit) || u->removing || u->owner!=owner || u->ownerRevision!=ownerRevision || u->deathRevision!=deathRevision || number(u->life)<=0){if(job.reserved)adjustFood(owner,-job.food,0);continue;}auto created=createUnit(owner,job.type,point->x,point->y,u->facing,job.reserved?job.food:0);recordStat(owner,&PlayerStatistics::trained);++statistics_.at(owner).typeScores[job.type].produced;if(alive(created.bits,NativeKind::Unit) && rally){if(alive(target,NativeKind::Unit)){auto destination=units_.at(target);rally=WorldPoint{destination->x,destination->y};}if(!target || !targetOrder(created.bits,target))moveUnit(created.bits,*rally);}if(alive(id,NativeKind::Unit) && !u->removing && u->owner==owner && u->ownerRevision==ownerRevision && u->deathRevision==deathRevision && number(u->life)>0){ScriptContext context;context.trainedType=job.type;context.trainedUnit=created.bits;unitEvent(id,34,71,context);startProduction(id);}continue;}
